class DefaultTemporaryLog(object):
    @property
    def default_dir(self):
        raise NotImplementedError

    def get_log_path(self, filename):
        return self.default_dir + filename

    @staticmethod
    def _get_dir_from_path(path):
        path = path.replace('\\', '/')
        items = path.split('/')
        if len(items) > 1:
            return '/'.join(items[0: -1]) + '/'
        else:
            return ''


class DefaultWindowsTemporaryLog(DefaultTemporaryLog):
    @property
    def default_dir(self):
        return self._get_dir_from_path(__file__) + "taf_tmp_logs/iperf/"


class DefaultLinuxTemporaryLog(DefaultTemporaryLog):
    @property
    def default_dir(self):
        return '/tmp/taf_tmp_logs/iperf/'
